solution.code:
@layer base, components, utilities;

:root {
  --color-primary: #3b82f6;
  --color-danger: #ef4444;
  --space-3: 12px;
  --radius: 8px;
}

@layer components {
  .btn {
    background: var(--color-primary);
    color: #fff;
    padding: var(--space-3) calc(var(--space-3) * 1.5);
    border: 0;
    border-radius: var(--radius);
  }
  .btn--danger { background: var(--color-danger); }
}

@layer utilities {
  .u-full { width: 100%; }
}
